public class AccessibilityDetector extends Detector implements XmlScanner {

    public static final Issue ISSUE = Issue.create(
        id = "ContentDescription",
        briefDescription = "Image without contentDescription",
        explanation = "Non-textual widgets like ImageViews and ImageButtons should use ...",
        category = Category.A11Y,
        priority = 3,
        severity = Severity.WARNING,
        implementation = Implementation(AccessibilityDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override public Collection<String> getApplicableElements() { return Arrays.asList(IMAGE_VIEW, IMAGE_BUTTON); }

    @Override public void visitElement(XmlContext context, Element element) {
        if (!element.hasAttributeNS(ANDROID_URI, ATTR_CONTENT_DESCRIPTION)) {
            // Check if importantForAccessibility="no" and minSdk >= 16
            if (element.hasAttributeNS(ANDROID_URI, ATTR_IMPORTANT_FOR_ACCESSIBILITY)) {
                String value = element.getAttributeNS(ANDROID_URI, ATTR_IMPORTANT_FOR_ACCESSIBILITY);
                if ("no".equals(value) && context.getProject().getMinSdk() >= 16) {
                    return;
                }
            }
            context.report(ISSUE, element, context.getLocation(element),
                "Missing `contentDescription` attribute on image");
        } else {
            // Check if contentDescription is @null? Not missing, fine.
            // Could also check text fields hint/contentDescription but not relevant.
        }
    }
}

